      border-radius: 8px;
      margin-bottom: 28px;
    }
    .info-item label {
      display: block;
      font-size: 11px;
      text-transform: uppercase;
      color: #94a3b8;
      font-weight: 600;
      margin-bottom: 2px;
    }
    .info-item span {
      font-size: 14px;
      font-weight: 600;
      color: #0f172a;
    }
    .stats-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 12px;
      margin-bottom: 28px;
    }
    .stat-box {
      background: #ffffff;
